import ast

src = 'def total(xs):\n    return sum(xs)\n\na = total([1])\nb = total([2])\n'
tree = ast.parse(src)

defs = {n.name: n.lineno for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)}
refs = {}
for n in ast.walk(tree):
    if isinstance(n, ast.Name) and n.id in defs and not isinstance(getattr(n, 'ctx', None), ast.Store):
        refs.setdefault(n.id, []).append(n.lineno)
# filter out the def line itself appearing as a Name (it doesn't; defs are FunctionDef)
print('definitions:', defs)
print('references of total:', [l for l in refs.get('total', [])])
print('LSP textDocument/references returns exactly this, type-aware, incremental')

import ast

src = 'x = 1\ny = x + 1\nx = 2\nz = x + y\n'
tree = ast.parse(src)

defs, uses = {}, []  # name -> defining line; uses: (name, line)
for node in ast.walk(tree):
    if isinstance(node, ast.Name):
        if isinstance(node.ctx, ast.Store):
            defs.setdefault(node.id, []).append(node.lineno)
        else:
            uses.append((node.id, node.lineno))

print('definitions:', defs)
for name, line in uses:
    reaching = [d for d in defs.get(name, []) if d < line]
    print('use of %s at line %d <- definitions at lines %s' % (name, line, reaching or ['?']))
print('rename is safe iff every use resolves to the renamed definition')

# shared symbol index across repos, version-pinned
index = {
    ('py-client', 'v1.2'): {'api.search': ('client.py', 42)},
    ('go-server', 'v3.1'): {'api.search': ('server.go', 17)},
}
lockfile = {'py-client': 'v1.2', 'go-server': 'v3.1'}  # pinned versions

def xref(repo, symbol):
    ver = lockfile[repo]
    return index.get((repo, ver), {}).get(symbol, 'not found')

print('py-client api.search ->', xref('py-client', 'api.search'))
print('go-server api.search ->', xref('go-server', 'api.search'))
print('same symbol name, two repos, pinned versions: no silent drift')

# symbol server: central index, editors query instead of parsing locally
server_index = {}

def ingest(repo, version, symbols):  # symbols: [(name, kind, file, line)]
    for name, kind, f, line in symbols:
        server_index.setdefault(name, []).append({'repo': repo, 'ver': version, 'kind': kind, 'at': (f, line)})

def query(name):
    return server_index.get(name, [])

ingest('web', 'a1b2', [('search', 'def', 'app.py', 10)])
ingest('web', 'a1b2', [('search', 'ref', 'views.py', 55)])
ingest('api', 'c3d4', [('search', 'def', 'api.py', 7)])
for hit in query('search'):
    print('%(repo)s@%(ver)s %(kind)s %(at)s' % hit)
print('parse once centrally -> every editor gets instant xrefs')

import ast

files = {
    'ui.py': 'import service\n',
    'service.py': 'import db\nimport util\n',
    'db.py': 'import util\n',
    'util.py': 'import service\n',  # cycle!
}
edges = {}
for f, src in files.items():
    mods = [n.names[0].name for n in ast.walk(ast.parse(src)) if isinstance(n, ast.Import)]
    edges[f] = [m + '.py' for m in mods if m + '.py' in files]

WHITE, GRAY, BLACK = 0, 1, 2
color = {f: WHITE for f in files}
cycle = []

def dfs(u, path):
    color[u] = GRAY
    for v in edges[u]:
        if color[v] == GRAY:
            cycle.extend(path[path.index(v):] + [v])
        elif color[v] == WHITE:
            dfs(v, path + [v])
    color[u] = BLACK

for f in files:
    if color[f] == WHITE:
        dfs(f, [f])
print('edges:', edges)
print('CYCLE:', ' -> '.join(cycle) if cycle else 'none')

# reverse call graph -> who is affected by changing 'db_write'?
edges = [('api', 'service'), ('service', 'db_write'), ('cli', 'db_write'), ('util', 'api')]
rev = {}
for a, b in edges:
    rev.setdefault(b, []).append(a)

def affected(sym):
    seen, stack = set(), [sym]
    while stack:
        s = stack.pop()
        for caller in rev.get(s, []):
            if caller not in seen:
                seen.add(caller)
                stack.append(caller)
    return seen

print('changing db_write affects:', sorted(affected('db_write')))
print('run only tests covering these, not the whole suite')

# sharded xref: query fans out to shards, merges results
shards = {
    'frontend/': {'Button': [('Button.tsx', 12)]},
    'backend/': {'Button': [('api.py', 88)]},  # same name, different symbol
}

def query(name):
    out = []
    for shard, idx in shards.items():  # fan-out (parallel in production)
        out.extend((shard + f, l) for f, l in idx.get(name, []))
    return out

print('refs to "Button":', query('Button'))
print('per-shard indexes merged at query time; staleness bounded by build graph')

# hybrid: keyword narrows, semantic ranks, xref signals re-rank
funcs = [
    ('fetch_with_retry', 'retries the http call with exponential backoff', 42),
    ('get_data', 'gets data from cache', 3),
    ('backoff_sleep', 'sleeps with exponential backoff between attempts', 17),
]
query_words = {'retry', 'backoff'}

def kw_score(doc):
    words = set(doc.lower().replace('_', ' ').split())
    return len(query_words & words)

ranked = sorted(funcs, key=lambda f: (kw_score(f[0] + ' ' + f[1]), f[2]), reverse=True)
for name, doc, refs in ranked:
    print('%-16s kw=%d refs=%-3d %s' % (name, kw_score(name + ' ' + doc), refs, doc))
print('semantic embeddings replace kw_score; xref ref-counts re-rank: same pipeline')
